#[derive(Debug)]
struct E(String);
impl From<std::num::ParseIntError> for E {
    fn from(e: std::num::ParseIntError) -> E { E(format!("parse: {}", e)) }
}
fn f(s: &str) -> Result<i32, E> {
    let n: i32 = s.parse()?;
    Ok(n * 2)
}
println!("{}", f("x").is_err());

